export function install(ctx){
 const resources=[['clients','Clientes',['view','create','edit','delete']],['products','Produtos',['view','create','edit','delete']],['quotes','Orçamentos',['view','create','print']],['workflow','Pedidos e produção',['view','edit']],['finance','Financeiro',['view','create','edit','delete','settle','reverse']],['bank','Extratos e conciliação',['view','import','reconcile']],['reports','Relatórios',['view','print']],['assets','Patrimônio',['view','create','edit']],['settings_production','Configurações · produção',['view','edit']],['settings_finance','Configurações · financeiro',['view','edit']],['settings_reports','Configurações · relatórios',['view','edit']],['settings_company','Configurações · empresa',['view','edit']],['settings_quotes','Configurações · orçamento',['view','edit']],['settings_appearance','Configurações · aparência',['view','edit']]];
 const labels={view:'Visualizar',create:'Cadastrar / gerar',edit:'Editar',delete:'Excluir',print:'Imprimir / PDF',settle:'Registrar baixa',reverse:'Estornar baixa',import:'Importar extrato',reconcile:'Conciliar'};
 async function permissionEditor(id){try{const perms=await ctx.api('/rest/v1/rpc/admin_user_permissions',{method:'POST',body:{p_user:id}});const d=document.createElement('dialog');d.style.width='min(800px,95vw)';d.innerHTML=`<h2>Permissões deste usuário</h2><p class="muted">As liberações são individuais. A administração de usuários e permissões é exclusiva do papel Administrador. Cadastros novos começam sem permissões.</p><form id="permissions-form"><div class="table-wrap"><table><thead><tr><th>Tela / área</th>${Object.values(labels).map(l=>`<th>${l}</th>`).join('')}</tr></thead><tbody>${resources.map(([key,label,actions])=>`<tr><td>${label}</td>${Object.keys(labels).map(a=>`<td>${actions.includes(a)?`<input style="width:18px;height:18px" type="checkbox" name="${key}.${a}" aria-label="${label}: ${labels[a]}" ${perms[key]?.[a]?'checked':''}>`:'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p id="permissions-error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" id="cancel-permissions">Cancelar</button><button type="submit" class="primary">Salvar permissões</button></div></form>`;document.body.append(d);d.showModal();ctx.$('#cancel-permissions').onclick=()=>d.close();d.onclose=()=>d.remove();ctx.$('#permissions-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const data={};for(const [r,,actions]of resources){data[r]={};for(const a of actions)data[r][a]=false}for(const key of new FormData(e.target).keys()){const [r,a]=key.split('.');data[r][a]=true}for(const [r] of resources){if(Object.entries(data[r]).some(([k,v])=>k!=='view'&&v))data[r].view=true}if(data.quotes.create){data.clients.view=true;data.products.view=true}if(data.bank.reconcile){data.finance.view=true}if(data.finance.settle){data.settings_finance.view=true}try{await ctx.api('/rest/v1/rpc/admin_set_permissions',{method:'POST',body:{p_user:id,p_permissions:data}});d.close();ctx.toast('Permissões individuais salvas.')}catch(err){ctx.$('#permissions-error').textContent=err.message;e.submitter.disabled=false}}}catch(e){ctx.toast(e.message)}}
 Object.assign(ctx,{permissionEditor});
}
